import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = 1;
        while (T > 0) {
            String s = sc.nextLine();
            if (s.length() == 1) {
                if ("0_ X".contains(s)) {
                    System.out.println(1);
                } else {
                    System.out.println(0);
                }
            } else {
                boolean foundX = false;
                for (char c : s.toCharArray()) {
                    if (c == 'X') {
                        foundX = true;
                        break;
                    }
                }
                if (!foundX) {
                    System.out.println(calculate(s));
                } else {
                    int totalSum = 0;
                    for (int digit = 0; digit <= 9; digit++) {
                        String replacedStr = s.replace('X', (char) (digit + '0'));
                        totalSum += calculate(replacedStr);
                    }
                    System.out.println(totalSum);
                }
            }
            T--;
        }
        sc.close();
    }

    public static int calculate(String s) {
        int len = s.length();
        int p = s.charAt(0) != '0' ? 1 : 0;
        for (int i = 0; i < len - 2; i++) {
            if (s.charAt(i) == '_') {
                p *= (i == 0) ? 9 : 10;
            }
        }
        int p1 = 0;
        if (s.charAt(len - 1) == '_' && s.charAt(len - 2) == '_') {
            p1 = (len == 2) ? 3 : 4;
        } else if (s.charAt(len - 1) == '_') {
            if ("0527".indexOf(s.charAt(len - 2)) >= 0) p1 = 1;
        } else if (s.charAt(len - 2) == '_') {
            if (s.charAt(len - 1) == '0') {
                p1 = (len == 2) ? 1 : 2;
            } else if (s.charAt(len - 1) == '5') {
                p1 = 2;
            }
        } else {
            int val = Integer.parseInt(s.substring(len - 2));
            if (val % 25 == 0) p1 = 1;
        }
        return p * p1;
    }
}
